def dichotomie(f, a, b, epsilon):
    """Retourne un encadrement d'un zéro de f sur [a,b] de largeur < epsilon.
    Précondition : f continue sur [a,b], f(a)*f(b) < 0."""
    while b - a > epsilon:
        m = (a + b) / 2
        if f(a) * f(m) <= 0:
            b = m
        else:
            a = m
    return a, b

# Exemple : zéro de x^3 - x - 1 sur [1,2]
f = lambda x: x**3 - x - 1
print(dichotomie(f, 1, 2, 1e-6))
